     1	//! Per-handle policy for the forced tool choice and the structured-output path.
     2	
     3	use std::sync::atomic::{AtomicBool, Ordering};
     4	
     5	use crate::family::{rejects_forced_tool_choice, ModelFamily};
     6	
     7	/// The wire path that carries a structured-output or forced-tool request.
     8	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
     9	pub(crate) enum OutputPath {
    10	    /// Use a synthetic forced tool.
    11	    ForcedTool,
    12	    /// Use the native structured-output field.
    13	    Native,
    14	}
    15	
    16	/// A notice that the native path changes the request. Each kind is logged once per handle.
    17	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    18	pub(crate) enum NativeNotice {
    19	    /// `ToolChoice::Required` is omitted.
    20	    RequiredOmitted,
    21	    /// `ToolChoice::Tool` is omitted.
    22	    ToolOmitted,
    23	    /// `ResponseFormat::JsonObject` degrades to text.
    24	    JsonObjectAsText,
    25	}
    26	
    27	/// State that selects the output path for one model handle.
    28	#[derive(Debug)]
    29	pub(crate) struct ForcedChoicePolicy {
    30	    rejects_static: bool,
    31	    learned: AtomicBool,
    32	    family: ModelFamily,
    33	    warned: [AtomicBool; 3],
    34	}
    35	
    36	impl ForcedChoicePolicy {
    37	    /// Make a policy. The static rule comes from the model id.
    38	    pub(crate) fn new(model_id: &str, family: ModelFamily) -> Self {
    39	        Self::with_rule(rejects_forced_tool_choice(model_id), family)
    40	    }
    41	
    42	    /// Make a policy with no static rule.
    43	    #[cfg(test)]
    44	    pub(crate) fn without_static_rule(family: ModelFamily) -> Self {
    45	        Self::with_rule(false, family)
    46	    }
    47	
    48	    fn with_rule(rejects_static: bool, family: ModelFamily) -> Self {
    49	        Self {
    50	            rejects_static,
    51	            learned: AtomicBool::new(false),
    52	            family,
    53	            warned: [
    54	                AtomicBool::new(false),
    55	                AtomicBool::new(false),
    56	                AtomicBool::new(false),
    57	            ],
    58	        }
    59	    }
    60	
    61	    /// The model family of this handle.
    62	    pub(crate) fn family(&self) -> ModelFamily {
    63	        self.family
    64	    }
    65	
    66	    /// The output path for the next request.
    67	    pub(crate) fn path(&self) -> OutputPath {
    68	        if self.rejects_static || self.learned.load(Ordering::SeqCst) {
    69	            OutputPath::Native
    70	        } else {
    71	            OutputPath::ForcedTool
    72	        }
    73	    }
    74	
    75	    /// Record that the service rejected a forced tool choice. Returns `true` only for the first call.
    76	    pub(crate) fn record_rejection(&self) -> bool {
    77	        !self.learned.swap(true, Ordering::SeqCst)
    78	    }
    79	
    80	    /// Returns `true` only the first time for each notice kind.
    81	    pub(crate) fn first_notice(&self, n: NativeNotice) -> bool {
    82	        !self.warned[n as usize].swap(true, Ordering::SeqCst)
    83	    }
    84	
    85	    /// Log the notice once per handle.
    86	    pub(crate) fn note(&self, n: NativeNotice, model_id: &str) {
    87	        if !self.first_notice(n) {
    88	            return;
    89	        }
    90	        let text = match n {
    91	            NativeNotice::RequiredOmitted => {
    92	                "ToolChoice::Required is omitted: this model rejects a forced tool choice"
    93	            }
    94	            NativeNotice::ToolOmitted => {
    95	                "ToolChoice::Tool is omitted: this model rejects a forced tool choice"
    96	            }
    97	            NativeNotice::JsonObjectAsText => {
    98	                "ResponseFormat::JsonObject degrades to text: native output cannot express a free-form object"
    99	            }
   100	        };
   101	        tracing::warn!(target: "paigasus::bedrock::translate", model_id = %model_id, "{text}");
   102	    }
   103	}
   104	
   105	#[cfg(test)]
   106	mod tests {
   107	    use super::*;
   108	    use ModelFamily::Anthropic;
   109	
   110	    #[test]
   111	    fn path_for_each_combination() {
   112	        assert_eq!(
   113	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5-5", Anthropic).path(),
   114	            OutputPath::Native
   115	        );
   116	        assert_eq!(
   117	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5", Anthropic).path(),
   118	            OutputPath::ForcedTool
   119	        );
   120	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
   121	        assert_eq!(p.path(), OutputPath::ForcedTool);
   122	        assert!(p.record_rejection());
   123	        assert_eq!(p.path(), OutputPath::Native);
   124	        let both = ForcedChoicePolicy::new("us.anthropic.claude-opus-5-5", Anthropic);
   125	        both.record_rejection();
   126	        assert_eq!(both.path(), OutputPath::Native);
   127	    }
   128	
   129	    #[test]
   130	    fn record_rejection_is_true_only_once_across_threads() {
   131	        let p = std::sync::Arc::new(ForcedChoicePolicy::without_static_rule(Anthropic));
   132	        let firsts: usize = (0..8)
   133	            .map(|_| {
   134	                let p = p.clone();
   135	                std::thread::spawn(move || p.record_rejection())
   136	            })
   137	            .collect::<Vec<_>>()
   138	            .into_iter()
   139	            .map(|h| h.join().unwrap() as usize)
   140	            .sum();
   141	        assert_eq!(firsts, 1);
   142	    }
   143	
   144	    #[test]
   145	    fn first_notice_is_true_once_per_kind() {
   146	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
   147	        assert!(p.first_notice(NativeNotice::RequiredOmitted));
   148	        assert!(!p.first_notice(NativeNotice::RequiredOmitted));
   149	        assert!(p.first_notice(NativeNotice::ToolOmitted));
   150	        assert!(p.first_notice(NativeNotice::JsonObjectAsText));
   151	    }
   152	}
