+    let forced_choice_rejected = match &err {
+        SdkError::ServiceError(svc) => {
+            is_forced_choice_rejection(svc.err().code(), svc.err().message().unwrap_or(""))
+        }
+        _ => false,
+    };
+    SendFailure {
+        forced_choice_rejected,
+        error: map_sdk_http_error(err),
+    }
+}
