168	        policy: &ForcedChoicePolicy,
169	        cfg: &Config,
170	        req: &ModelRequest,
171	        script: Vec<Result<(), SendFailure>>,
172	    ) -> (Result<Sent<()>, ModelError>, Vec<Value>) {
173	        let first = build_request(cfg, req, policy.path()).expect("first request");
174	        let sent: Arc<Mutex<Vec<Value>>> = Arc::new(Mutex::new(Vec::new()));
175	        let script = Arc::new(Mutex::new(VecDeque::from(script)));
176	        let send = {
177	            let sent = sent.clone();
178	            let script = script.clone();
179	            move |p: crate::translate::PreparedConverse| {
180	                sent.lock().unwrap().push(to_wire_json(&p));
181	                let next = script
182	                    .lock()
183	                    .unwrap()
184	                    .pop_front()
185	                    .expect("a send that the script does not cover");
186	                async move { next }
187	            }
188	        };
189	        let rt = tokio::runtime::Builder::new_current_thread()
190	            .enable_all()
191	            .build()
192	            .expect("tokio runtime");
193	        let result = rt.block_on(send_with_fallback(
194	            policy,
195	            &cfg.model_id,
196	            first,
197	            |path| build_request(cfg, req, path),
198	            send,
199	        ));
200	        let wires = sent.lock().unwrap().clone();
201	        (result, wires)
202	    }
