  1	//! The single send fallback for a forced tool choice that the service rejects.
  2	//!
  3	//! An Anthropic model on Bedrock can reject a forced tool choice
  4	//! (`toolChoice` `any` or `tool`) with a `ValidationException`. When the
  5	//! first request carried a forced choice and the service rejects it before
  6	//! the stream starts, the provider sends the request one more time on the
  7	//! native structured-output path. The handle then records the rejection, and
  8	//! all later requests on the handle use the native path at once.
  9	//!
 10	//! This fallback does not break ADR-10 (*No silent auto-retry inside the
 11	//! loop*), for four reasons. The fallback sends a *different* request, not
 12	//! the same request again. It occurs at most once for each request. It is
 13	//! logged. It never follows a transient error (throttling, a 5xx error or a
 14	//! transport error): those errors go to the caller unchanged.
 15	//!
 16	//! The match on the error text is a weak contract. If Bedrock changes the
 17	//! text, the result is the same `ValidationException` as before this
 18	//! fallback existed. The static model-id rule still sends the known models
 19	//! on the native path from the first request.
 20	
 21	use std::future::Future;
 22	
 23	use paigasus_helikon_core::ModelError;
 24	
 25	use crate::error::SendFailure;
 26	use crate::family::ModelFamily;
 27	use crate::policy::{ForcedChoicePolicy, OutputPath};
 28	use crate::translate::PreparedConverse;
 29	
 30	/// The output of a send, with the `synthesizing` value of the request that
 31	/// was actually sent.
 32	#[derive(Debug)]
 33	pub(crate) struct Sent<T> {
 34	    /// The output of the send.
 35	    pub(crate) output: T,
 36	    /// `synthesizing` of the request that was sent.
 37	    pub(crate) synthesizing: bool,
 38	}
 39	
 40	/// Send `first`. If the service rejects its forced tool choice, send the
 41	/// request again on the native path, one time.
 42	///
 43	/// The fallback occurs only when all of these conditions are true:
 44	/// the model family is Anthropic, `first` carried a forced tool choice, and
 45	/// the failure is a rejection of that choice. `rebuild` makes the native
 46	/// request. An error from the second send goes to the caller with no
 47	/// further fallback.
 48	pub(crate) async fn send_with_fallback<T, B, S, Fut>(
 49	    policy: &ForcedChoicePolicy,
 50	    model_id: &str,
 51	    first: PreparedConverse,
 52	    rebuild: B,
 53	    mut send: S,
 54	) -> Result<Sent<T>, ModelError>
 55	where
 56	    B: FnOnce(OutputPath) -> Result<PreparedConverse, ModelError>,
 57	    S: FnMut(PreparedConverse) -> Fut,
 58	    Fut: Future<Output = Result<T, SendFailure>>,
 59	{
 60	    for n in &first.notices {
 61	        policy.note(*n, model_id);
 62	    }
 63	    let synthesizing = first.synthesizing;
 64	    let first_was_forced = first.has_forced_tool_choice();
 65	
 66	    let failure = match send(first).await {
 67	        Ok(output) => {
 68	            return Ok(Sent {
 69	                output,
 70	                synthesizing,
 71	            })
 72	        }
 73	        Err(f) => f,
 74	    };
 75	
 76	    if !(policy.family() == ModelFamily::Anthropic
 77	        && first_was_forced
 78	        && failure.forced_choice_rejected)
 79	    {
 80	        return Err(failure.error);
 81	    }
 82	
 83	    if policy.record_rejection() {
 84	        tracing::warn!(
 85	            target: "paigasus::bedrock::model",
 86	            model_id = %model_id,
 87	            "the model rejected a forced tool choice; native structured output is now in use for this handle"
 88	        );
 89	    }
 90	
 91	    let second = rebuild(OutputPath::Native)?;
 92	    for n in &second.notices {
 93	        policy.note(*n, model_id);
 94	    }
 95	    let synthesizing = second.synthesizing;
 96	    match send(second).await {
 97	        Ok(output) => Ok(Sent {
 98	            output,
 99	            synthesizing,
100	        }),
101	        Err(f) => Err(f.error),
102	    }
103	}
