     1	//! The request on the native structured-output path.
     2	//!
     3	//! Some models reject a forced tool choice (`toolChoice: any` or `tool`). For
     4	//! these models the provider sends a `JsonSchema` response format in
     5	//! `outputConfig.textFormat` and never forces a tool call. Each change of
     6	//! meaning is recorded as a [`NativeNotice`] on the result.
     7	
     8	use aws_sdk_bedrockruntime::types::{
     9	    AutoToolChoice, ContentBlock, JsonSchemaDefinition, OutputConfig, OutputFormat,
    10	    OutputFormatStructure, OutputFormatType, Tool, ToolChoice as BedrockToolChoice,
    11	};
    12	use paigasus_helikon_core::{ModelError, ModelRequest, ResponseFormat, ToolChoice};
    13	
    14	use crate::builder::Config;
    15	use crate::policy::NativeNotice;
    16	use crate::translate::native_schema::native_output_schema;
    17	use crate::translate::request::items_to_messages;
    18	use crate::translate::response_format::synthesize;
    19	use crate::translate::schema::Ruleset;
    20	use crate::translate::tools::tool_specs;
    21	use crate::translate::{
    22	    assemble_tool_config, build_inference_config, check_tool_name, required_without_tools_error,
    23	    PreparedConverse,
    24	};
    25	
    26	/// Assemble a [`PreparedConverse`] for the native path.
    27	///
    28	/// - `JsonSchema` goes to `outputConfig`. The `strict` flag has no effect.
    29	/// - `JsonObject` degrades to text, because native output cannot express a
    30	///   free-form object.
    31	/// - `ToolChoice::Required` and `ToolChoice::Tool` are omitted. `Auto` stays.
    32	/// - After a tool round with no user tools, the synthesized tool is sent as a
    33	///   `toolConfig` anchor without a `toolChoice`, because Bedrock needs a
    34	///   `toolConfig` when the history holds a tool call or a tool result.
    35	///
    36	/// # Errors
    37	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
    38	/// - `ToolChoice::Required` with no tool and no structured response format.
    39	/// - `ToolChoice::Tool` with a name that is not in the tool list.
    40	/// - The message errors of `items_to_messages`.
    41	/// - An SDK builder error.
    42	pub(crate) fn build_native(
    43	    cfg: &Config,
    44	    req: &ModelRequest,
    45	) -> Result<PreparedConverse, ModelError> {
    46	    let family = cfg.family;
    47	    let ruleset = Ruleset::for_family(family);
    48	    let rf = req.model_settings.response_format.as_ref();
    49	    let tool_choice = req.model_settings.tool_choice.as_ref();
    50	    let mut notices = Vec::new();
    51	
    52	    let translated = items_to_messages(&req.messages)?;
    53	
    54	    // Response format.
    55	    let structured = matches!(
    56	        rf,
    57	        Some(ResponseFormat::JsonSchema { .. } | ResponseFormat::JsonObject)
    58	    );
    59	    let output_config = match rf {
    60	        Some(ResponseFormat::JsonSchema { name, schema, .. }) => {
    61	            Some(json_schema_output_config(name, schema)?)
    62	        }
    63	        Some(ResponseFormat::JsonObject) => {
    64	            notices.push(NativeNotice::JsonObjectAsText);
    65	            None
    66	        }
    67	        _ => None,
    68	    };
    69	
    70	    // User tools. `ToolChoice::None` sends no user tools.
    71	    let mut all_tools: Vec<Tool> = if matches!(tool_choice, Some(ToolChoice::None)) {
    72	        Vec::new()
    73	    } else {
    74	        tool_specs(&req.tools, ruleset)?
    75	            .into_iter()
    76	            .map(Tool::ToolSpec)
    77	            .collect()
    78	    };
    79	
    80	    // Anchor: a structured format, no user tools and a tool round in the history.
    81	    let mut synthesizing = false;
    82	    if structured && all_tools.is_empty() && has_tool_round(&translated.messages) {
    83	        if let Some(anchor) = synthesize(rf, family, ruleset)?.tool {
    84	            all_tools.push(Tool::ToolSpec(anchor));
    85	            synthesizing = true;
    86	        }
    87	    }
    88	
    89	    // Tool choice. The native path never forces a tool call.
    90	    let choice = match tool_choice {
    91	        None | Some(ToolChoice::None) => None,
    92	        Some(ToolChoice::Auto) => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
    93	        Some(ToolChoice::Required) => {
    94	            if all_tools.is_empty() && !structured {
    95	                return Err(required_without_tools_error());
    96	            }
    97	            notices.push(NativeNotice::RequiredOmitted);
    98	            None
    99	        }
   100	        Some(ToolChoice::Tool { name }) => {
   101	            check_tool_name(&all_tools, name)?;
   102	            notices.push(NativeNotice::ToolOmitted);
   103	            None
   104	        }
   105	        Some(_) => {
   106	            tracing::debug!(
   107	                target: "paigasus::bedrock::translate",
   108	                "unknown ToolChoice variant; omitting",
   109	            );
   110	            None
   111	        }
   112	    };
   113	
   114	    let tool_config = assemble_tool_config(all_tools, choice)?;
   115	    let inference_config = build_inference_config(req, cfg);
   116	
   117	    Ok(PreparedConverse {
   118	        model_id: cfg.model_id.clone(),
   119	        system: translated.system,
   120	        messages: translated.messages,
   121	        tool_config,
   122	        inference_config,
   123	        synthesizing,
   124	        output_config,
   125	        notices,
   126	    })
   127	}
   128	
   129	/// Returns `true` when a message holds a tool call or a tool result.
   130	fn has_tool_round(messages: &[aws_sdk_bedrockruntime::types::Message]) -> bool {
   131	    messages.iter().any(|m| {
   132	        m.content()
   133	            .iter()
   134	            .any(|b| matches!(b, ContentBlock::ToolUse(_) | ContentBlock::ToolResult(_)))
   135	    })
   136	}
   137	
   138	/// Make the `outputConfig` for a `JsonSchema` response format.
   139	fn json_schema_output_config(
   140	    name: &str,
   141	    schema: &serde_json::Value,
   142	) -> Result<OutputConfig, ModelError> {
   143	    let builder_error = |e| {
   144	        ModelError::Other(anyhow::anyhow!(
   145	            "failed to build the native output config: {e}"
   146	        ))
   147	    };
   148	    let schema = serde_json::to_string(&native_output_schema(schema)).map_err(|e| {
   149	        ModelError::Other(anyhow::anyhow!(
   150	            "failed to serialize the native output schema: {e}"
   151	        ))
   152	    })?;
   153	    let definition = JsonSchemaDefinition::builder()
   154	        .schema(schema)
   155	        .name(name)
   156	        .build()
   157	        .map_err(builder_error)?;
   158	    let format = OutputFormat::builder()
   159	        .r#type(OutputFormatType::JsonSchema)
   160	        .structure(OutputFormatStructure::JsonSchema(definition))
   161	        .build()
   162	        .map_err(builder_error)?;
   163	    Ok(OutputConfig::builder().text_format(format).build())
   164	}
